style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com"), domain("web.roblox.com") {
html, body {
        background: url("https://images.steamusercontent.com/ugc/2011457496837087021/6133DBA76E3048FD726953E035736BFB5AC305A8/?imw=512&&ima=fit&impolicy=Letterbox&imcolor=%23000000&letterbox=false") 
            no-repeat center center fixed !important;
        background-size: cover !important;
        background-color: black !important;
    }

    /* Make main containers transparent so background shows */
    .dark-theme, 
    .container-main, 
    .home-container, 
    .flex-container, 
    .game-home-page, 
    .section, 
    .scroller-content, 
    .content, 
    .app, 
    .app-content {
        background-color: rgba(0, 0, 0, 0.5) !important;
    }

    /* Transparent sidebar and navbar */
    .left-navigation, 
    .header, 
    .header-navbar, 
    .nav-container, 
    .menu-bar {
        background-color: rgba(0, 0, 0, 0.4) !important;
    }

    /* Optional: remove all other background images */
    * {
        background-image: none !important;
    }
}
